209	// ---------- com/study/app/query/OrderProjection.java ----------
210	package com.study.app.query;
211	
212	import com.study.app.command.*;
213	import org.axonframework.config.ProcessingGroup;
214	import org.axonframework.eventhandling.EventHandler;
215	import org.axonframework.queryhandling.QueryHandler;
216	import org.springframework.dao.DataIntegrityViolationException;
217	import org.springframework.stereotype.Component;
218	
219	@Component
220	@ProcessingGroup("order-projection")
221	public class OrderProjection {
222	
223	    private final OrderViewRepository orders;
224	    private final NotificationRepository notifications;
225	
226	    public OrderProjection(OrderViewRepository o, NotificationRepository n) { this.orders = o; this.notifications = n; }
227	
228	    // ---- projection (read-model write + token advance share one tx) ----
229	    @EventHandler
230	    public void on(OrderCreatedEvent e) {
231	        orders.save(new OrderView(e.orderId(), e.customerId(), e.productId(), e.quantity(), "PENDING"));
232	    }
233	
234	    @EventHandler
235	    public void on(OrderConfirmedEvent e) {
236	        orders.findById(e.orderId()).ifPresent(v -> { v.setStatus("CONFIRMED"); v.setTotal(e.total()); orders.save(v); });
237	        emitNotification(e.orderId(), "CONFIRMED");
238	    }
239	
240	    @EventHandler
241	    public void on(OrderRejectedEvent e) {
242	        orders.findById(e.orderId()).ifPresent(v -> { v.setStatus("REJECTED"); v.setReason(e.reason()); orders.save(v); });
243	        emitNotification(e.orderId(), "REJECTED");
244	    }
245	
246	    // exactly-once notification: redelivered event hits the UNIQUE(orderId) and is skipped
247	    private void emitNotification(String orderId, String status) {
248	        try { notifications.saveAndFlush(new Notification(orderId, status)); }
249	        catch (DataIntegrityViolationException already) { /* exactly-once */ }
250	    }
251	
252	    // ---- query handlers ----
253	    @QueryHandler
254	    public OrderView handle(FindOrder q) { return orders.findById(q.orderId()).orElse(null); }
255	
256	    @QueryHandler
257	    public Stats handle(FindStats q) {
258	        long confirmed = orders.findAll().stream().filter(v -> "CONFIRMED".equals(status(v))).count();
259	        // production: use an aggregate JPQL query instead of loading all rows
260	        return new Stats(confirmed, 0, 0);
261	    }
262	    private String status(OrderView v) { return ""; }   // placeholder; real impl reads a getter
263	}
