            return; // idempotent: already processed
        }
        if (balance >= cmd.amount()) {
            apply(new FundsChargedEvent(customerId, cmd.orderId(), cmd.amount()));
        } else {
            apply(new ChargeFailedEvent(customerId, cmd.orderId(), cmd.productId(), cmd.quantity()));
